const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const badge=p=>`<span class="badge ${p.st[0]}">${p.st[1]}</span>`;
const techs=p=>`<div class="techs">${p.t.map(x=>`<span>${esc(x)}</span>`).join("")}</div>`;
$("#cards").innerHTML=P.map(p=>`<article class="card"><span class="cat">${esc(p.cat)}</span><h3>${esc(p.n)}</h3><p>${esc(p.d)}</p>${techs(p)}<div>${badge(p)}</div><a class="btn" href="#${p.id}" aria-label="Ver ficha técnica de ${esc(p.n)}">Ver ficha técnica</a></article>`).join("");
$("#areas").innerHTML=A.map(a=>`<div class="card"><h3>${a[0]}</h3><p>${a[1]}</p></div>`).join("");

function ficha(p){
 document.title=p.n+" | DigiNOSIA";
 $("#ficha").innerHTML=`<section><p class="crumbs"><a href="#proyectos">← Volver a proyectos</a></p>
 <span class="cat">${esc(p.cat)}</span><h1 style="max-width:none">${esc(p.n)}</h1><p class="tags" style="font-size:1.1rem;color:var(--tx2);font-family:var(--body)">${esc(p.d)}</p>
 <div class="fgrid"><div><h2>Qué es</h2><p>${esc(p.sum)}</p><h2>Funcionalidades</h2><ul>${p.f.map(x=>`<li>${esc(x)}</li>`).join("")}</ul><h2>Valor tecnológico</h2><p>${esc(p.v)}</p>${arqHtml(p)}
 ${p.nota?`<p class="note">${esc(p.nota)}</p>`:""}
 <p class="note">Pendiente de completar con evidencias reales: capturas, diagrama de arquitectura y mejoras previstas (separadas de lo ya implementado).</p></div>
 <aside class="side" aria-label="Datos del proyecto"><h3>Estado</h3><p>${badge(p)}</p><h3>Tecnologías</h3>${techs(p)}<h3>Acceso</h3>
 ${acc(p)}${relh(p)}</aside></div>${pn(p)}</section>`;
}
function route(){
 const h=decodeURIComponent(location.hash.slice(1));
 const p=P.find(x=>x.id===h);
 document.body.classList.toggle("in-ficha",!!p);
 if(p){ficha(p);window.scrollTo(0,0);$("#ficha h1").setAttribute("tabindex","-1");$("#ficha h1").focus({preventScroll:true})}
 else{showPage(h)}
 document.querySelectorAll("nav a").forEach(a=>a.toggleAttribute("aria-current",a.getAttribute("href")==="#"+(h||"inicio")||(p&&a.getAttribute("href")==="#proyectos")));
 closeMenu();
}
const mb=$("#menu-btn"),menu=$("#menu");
function closeMenu(){menu.classList.remove("open");mb.setAttribute("aria-expanded","false")}
mb.onclick=()=>{const o=menu.classList.toggle("open");mb.setAttribute("aria-expanded",o)};
document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeMenu();$("#a11y").classList.remove("open");$("#a11y-btn").setAttribute("aria-expanded","false")}});
addEventListener("hashchange",route);route();

/* accesibilidad */
const root=document.documentElement;let pref={fs:1,theme:"auto"};
try{Object.assign(pref,JSON.parse(localStorage.getItem("dg-a11y")||"{}"))}catch(e){}
function apply(){root.style.setProperty("--fs",pref.fs);pref.theme==="auto"?root.removeAttribute("data-theme"):root.setAttribute("data-theme",pref.theme);try{localStorage.setItem("dg-a11y",JSON.stringify(pref))}catch(e){}}
apply();
const ab=$("#a11y-btn"),panel=$("#a11y"),stt=$("#a11y-status");
ab.onclick=()=>{const o=panel.classList.toggle("open");ab.setAttribute("aria-expanded",o)};
panel.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;
 if(b.dataset.fs){pref.fs=Math.min(1.5,Math.max(.8,+(pref.fs+ +b.dataset.fs).toFixed(2)));stt.textContent="Tamaño del texto: "+Math.round(pref.fs*100)+" %"}
 if(b.dataset.theme){pref.theme=b.dataset.theme;stt.textContent="Tema aplicado"}
 if(b.id==="reset"){pref={fs:1,theme:"auto"};stt.textContent="Preferencias restablecidas"}
 apply()});
$("#read").onclick=()=>{
 if(!("speechSynthesis" in window)){stt.textContent="Tu navegador no ofrece lectura en voz alta.";return}
 speechSynthesis.cancel();const u=new SpeechSynthesisUtterance($("#main").innerText.slice(0,4000));u.lang="es-ES";speechSynthesis.speak(u);stt.textContent="Leyendo el contenido de la página"};
$("#stop").onclick=()=>{if("speechSynthesis" in window)speechSynthesis.cancel();stt.textContent="Lectura detenida"};

function showPage(h){
 var T={inicio:["inicio","marca","espi","illi","destacados"],proyectos:["proyectos"],especialidades:["especialidades","ilustraciones"],metodologia:["metodologia"],sobre:["sobre"],perfil:["perfil"],contacto:["contacto"]};
 var N={inicio:"Inicio",proyectos:"Proyectos",especialidades:"Especialidades",metodologia:"Metodología",sobre:"Sobre DigiNOSIA",perfil:"Perfil profesional",contacto:"Contacto"};
 if(!T[h])h="inicio";
 document.querySelectorAll("#home>section").forEach(s=>s.classList.toggle("on",T[h].includes(s.id)));
 document.title=h==="inicio"?"DigiNOSIA | Software, Inteligencia Artificial, Datos y Automatización":N[h]+" | DigiNOSIA";
 $("#sr").textContent="Página: "+N[h];
 if(showPage.n){window.scrollTo(0,0);var hd=document.querySelector("#home>section.on h1,#home>section.on h2");if(hd){hd.setAttribute("tabindex","-1");hd.focus({preventScroll:true})}}
 showPage.n=1;
}
function pn(p){var i=P.indexOf(p),a=P[i-1],b=P[i+1];return '<nav class="pn" aria-label="Otros proyectos">'+(a?'<a class="btn" href="#'+a.id+'">← '+esc(a.n)+'</a>':'<span></span>')+(b?'<a class="btn" href="#'+b.id+'">'+esc(b.n)+' →</a>':'')+'</nav>'}

/* destacados y filtros */
$("#feat").innerHTML=["hisdatawiki","codisalud","devacademy","poo-object-lab"].map(id=>P.find(x=>x.id===id)).map(p=>`<article class="card"><span class="cat">${esc(p.cat)}</span><h3>${esc(p.n)}</h3><p>${esc(p.d)}</p>${techs(p)}<div>${badge(p)}</div><a class="btn" href="#${p.id}" aria-label="Ver ficha técnica de ${esc(p.n)}">Ver ficha técnica</a></article>`).join("");
function flt(){var q=$("#q").value.toLowerCase(),c=$("#cat").value,re=c?new RegExp(c):null,n=0;
 document.querySelectorAll("#cards .card").forEach(el=>{var t=el.textContent,ok=(!q||t.toLowerCase().includes(q))&&(!re||re.test(t));el.hidden=!ok;if(ok)n++});
 $("#count").textContent=n+(n===1?" proyecto":" proyectos")+(n?"":". Prueba con otra búsqueda.")}
$("#q").oninput=flt;$("#cat").onchange=flt;flt();

/* animación al hacer scroll */
var io="IntersectionObserver" in window?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("vis");io.unobserve(e.target)}}),{threshold:.1}):null;
document.querySelectorAll(".card,.steps li,.eco>div").forEach(el=>{el.classList.add("rv");io?io.observe(el):el.classList.add("vis")});
addEventListener("scroll",()=>{var d=document.documentElement,m=d.scrollHeight-innerHeight;$("#prog").style.width=(m>0?scrollY/m*100:0)+"%";$("#top").hidden=scrollY<600},{passive:true});
$("#top").onclick=()=>scrollTo({top:0});

/* preferencias ampliadas */
var K="dg-a11y2",Q={lh:0,ls:0,ws:0,ms:0,font:"",filter:"",rate:1,voice:"",t:[]};
try{Object.assign(Q,JSON.parse(localStorage.getItem(K)||"{}"))}catch(e){}
var CY={lh:["Interlineado",[1.6,1.9,2.2],"--lh",""],ls:["Letras",[0,.05,.1],"--ls","em"],ws:["Palabras",[0,.12,.25],"--ws","em"],ms:["Ancho de línea",[68,56,44],"--measure","ch"]};
var TG={links:"t-links",focus:"t-focus",ruler:"t-ruler",paused:"no-motion",simple:"t-simple",nokeys:""};
function apply2(){var r=document.documentElement;
 for(var k in CY){var c=CY[k];r.style.setProperty(c[2],c[1][Q[k]]+c[3]);document.querySelector('[data-cycle="'+k+'"]').textContent=c[0]+": "+(Q[k]+1)+"/3"}
 r.dataset.font=Q.font;
 ["gray","protan","deutan","tritan"].forEach(f=>r.classList.toggle("f-"+f,Q.filter===f));
 for(var t in TG){var on=Q.t.includes(t);if(TG[t])r.classList.toggle(TG[t],on);document.querySelector('[data-tog="'+t+'"]').setAttribute("aria-pressed",on)}
 $("#p-font").value=Q.font;$("#p-filter").value=Q.filter;$("#p-rate").value=Q.rate;$("#p-voice").value=Q.voice;
 try{localStorage.setItem(K,JSON.stringify(Q))}catch(e){}}
panel.addEventListener("click",e=>{var b=e.target.closest("button");if(!b)return;
 if(b.dataset.cycle){var k=b.dataset.cycle;Q[k]=(Q[k]+1)%3;stt.textContent=CY[k][0]+" actualizado"}
 if(b.dataset.tog){var t=b.dataset.tog,i=Q.t.indexOf(t);i<0?Q.t.push(t):Q.t.splice(i,1);stt.textContent="Opción actualizada"}
 if(b.id==="reset")Q={lh:0,ls:0,ws:0,ms:0,font:"",filter:"",rate:1,voice:"",t:[]};
 if(b.id==="keysbtn")$("#keys").showModal();
 apply2()});
$("#p-font").onchange=e=>{Q.font=e.target.value;apply2()};
$("#p-filter").onchange=e=>{Q.filter=e.target.value;apply2()};
$("#p-voice").onchange=e=>{Q.voice=e.target.value;apply2()};
$("#p-rate").oninput=e=>{Q.rate=+e.target.value;apply2()};

/* voz */
function vs(){var s=$("#p-voice"),v=speechSynthesis.getVoices().filter(x=>/^es/i.test(x.lang));s.innerHTML='<option value="">Voz predeterminada</option>'+v.map(x=>'<option value="'+esc(x.name)+'">'+esc(x.name)+'</option>').join("");s.value=Q.voice}
if("speechSynthesis" in window){vs();speechSynthesis.onvoiceschanged=vs}
function say(txt){if(!("speechSynthesis" in window)){stt.textContent="Tu navegador no ofrece lectura en voz alta.";return}speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(txt);u.lang="es-ES";u.rate=+Q.rate;var v=speechSynthesis.getVoices().find(x=>x.name===Q.voice);if(v)u.voice=v;speechSynthesis.speak(u)}
$("#read").onclick=()=>{var els=document.body.classList.contains("in-ficha")?[$("#ficha")]:[...document.querySelectorAll("#home>section.on")];say(els.map(e=>e.innerText).join(". ").slice(0,6000));stt.textContent="Leyendo la página"};
$("#readsel").onclick=()=>{var s=String(getSelection());if(s){say(s);stt.textContent="Leyendo la selección"}else stt.textContent="Selecciona primero un texto en la página."};

/* regla de lectura */
var RL=$("#ruler");function mv(y){RL.style.top=Math.max(0,y-24)+"px"}
addEventListener("pointermove",e=>mv(e.clientY));addEventListener("focusin",e=>{var r=e.target.getBoundingClientRect();mv(r.top+r.height/2)});

/* atajos */
var G=0;
document.addEventListener("keydown",e=>{if(Q.t.includes("nokeys")||e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName))return;
 var m={i:"inicio",p:"proyectos",e:"especialidades",m:"metodologia",s:"sobre",c:"contacto"},d=$("#keys");
 if(e.key==="?"&&!d.open){d.showModal();return}
 if(e.key==="/"){e.preventDefault();location.hash="#proyectos";setTimeout(()=>$("#q").focus(),60);return}
 if(e.key==="g"){G=Date.now();return}
 if(Date.now()-G<1500&&m[e.key])location.hash="#"+m[e.key];
 G=0});

/* contacto */
$("#copy").onclick=()=>{var s=$("#cf-s");navigator.clipboard&&navigator.clipboard.writeText("nosia_sl@hotmail.com").then(()=>{s.textContent="Dirección copiada."},()=>{s.textContent="No se pudo copiar. La dirección es nosia_sl@hotmail.com."})||(s.textContent="La dirección es nosia_sl@hotmail.com.")};
$("#cf").addEventListener("submit",e=>{e.preventDefault();var bad=0;
 [["cn","Escribe tu nombre."],["cm","Introduce una dirección de correo válida."],["cx","Escribe un mensaje."]].forEach(a=>{var i=$("#"+a[0]),ok=i.value.trim()&&i.checkValidity();$("#"+a[0]+"-e").textContent=ok?"":"⚠ "+a[1];i.setAttribute("aria-invalid",!ok);if(!ok&&!bad){bad=1;i.focus()}else if(!ok)bad=1});
 if(bad)return;
 var u="mailto:nosia_sl@hotmail.com?subject="+encodeURIComponent($("#cs").value||"Contacto desde DigiNOSIA")+"&body="+encodeURIComponent("Nombre: "+$("#cn").value+"\nCorreo: "+$("#cm").value+"\n\n"+$("#cx").value);
 $("#cf-s").innerHTML='Mensaje preparado. <a href="'+esc(u)+'">Abrir en tu programa de correo</a> o escribe directamente a nosia_sl@hotmail.com.';
 try{location.href=u}catch(x){}});

apply2();

