var PJ=[["HISdataWiki","hisdatawiki","Proyecto orientado a la organización del conocimiento sanitario, la información y la estadística. Representa la aplicación de programación, estructuración documental y herramientas de consulta.","ABCD"],["CodiSalud","codisalud","Aplicación educativa centrada en la práctica de codificación CIE-10-ES, con orientación al aprendizaje, evaluación y autoentrenamiento.","ADE"],["DevAcademy","devacademy","Entorno de aprendizaje tecnológico con contenidos estructurados, recursos didácticos y ejercicios prácticos.","AE"],["POO Object Lab","poo-object-lab","Proyecto educativo para comprender la programación orientada a objetos mediante simulaciones y representaciones visuales.","ACE"],["Rutas del Alma: Ecos y Sombras","rutas-del-alma","Proyecto editorial y creativo que conecta narrativa, ilustración, publicación digital y experiencias interactivas mediante juegos.","AFG"],["Games Rutas del Alma","games","Desarrollo de prototipos de videojuegos y experiencias interactivas vinculadas al universo narrativo del proyecto editorial.","AG"],["DigiNOSIA","","Identidad profesional y espacio de integración de proyectos tecnológicos, educativos, sanitarios y creativos.","ABCDEFG"]];
