function selS(k,user){spi=k;document.querySelectorAll(".spr").forEach((b,i)=>{var on=i===k;b.setAttribute("aria-selected",on);b.tabIndex=on?0:-1});
 var s=S[k],re=new RegExp(s[3]),n=0;document.querySelectorAll("#cards .card").forEach(c=>{if(re.test(c.textContent))n++});
 var st=$("#spstage");st.setAttribute("aria-labelledby","spt"+k);
 st.innerHTML='<div class="stg"><div class="stgi">'+sv(s[4])+'</div><div><h4>'+esc(s[0])+'</h4><p>'+esc(s[1])+'</p><h5 class="eyebrow" style="margin:1rem 0 .3rem">Áreas de trabajo</h5><ul>'+s[2].map((x,j)=>'<li style="--i:'+j+'">'+esc(x)+'</li>').join("")+'</ul><button type="button" class="btn p" data-f="'+esc(s[3])+'">Ver proyectos relacionados</button><span class="cnt">'+n+(n===1?" proyecto":" proyectos")+'</span></div></div>';
 st.querySelectorAll("svg *").forEach(e=>e.setAttribute("pathLength","1"));
 document.querySelectorAll("#spill .ill").forEach(f=>f.classList.toggle("act",+f.dataset.k===k));
 if(user){spa=false;$("#spw").classList.remove("auto");upBtn()}}
$("#splist").innerHTML=S.map((s,k)=>'<button type="button" role="tab" class="spr" id="spt'+k+'" data-k="'+k+'" style="--i:'+k+'" aria-selected="'+(k===0)+'" aria-controls="spstage" tabindex="'+(k?-1:0)+'"><b>0'+(k+1)+'</b>'+esc(s[0])+'</button>').join("");
$("#splist").addEventListener("click",e=>{var b=e.target.closest(".spr");if(b)selS(+b.dataset.k,true)});
$("#splist").addEventListener("keydown",e=>{var d={ArrowDown:1,ArrowRight:1,ArrowUp:5,ArrowLeft:5}[e.key];if(!d)return;e.preventDefault();var n=(spi+d)%6;selS(n,true);document.getElementById("spt"+n).focus()});
$("#splist").addEventListener("animationend",e=>{if(e.animationName==="fillbar"&&spa)selS((spi+1)%6,false)});
$("#spstage").addEventListener("click",e=>{var b=e.target.closest("[data-f]");if(!b)return;$("#cat").value=b.dataset.f;$("#q").value="";flt();location.hash="#proyectos"});
$("#spstage").addEventListener("pointermove",e=>{if(rm)return;var t=e.currentTarget,r=t.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5,i=t.querySelector(".stgi svg");if(i){i.style.setProperty("--ry",(x*14)+"deg");i.style.setProperty("--rx",(-y*14)+"deg")}});
$("#spstage").addEventListener("pointerleave",e=>{var i=e.currentTarget.querySelector(".stgi svg");if(i){i.style.setProperty("--ry","0deg");i.style.setProperty("--rx","0deg")}});
$("#spauto").hidden=rm;
$("#spauto").onclick=()=>{spa=!spa;$("#spw").classList.toggle("auto",spa);upBtn();if(spa){var b=document.getElementById("spt"+spi);b.style.animation="none";b.offsetWidth;b.style.animation=""}};
