function bmcH(p,s,a){var ch=(p.demo?"Aplicación en GitHub Pages; ":"")+(p.r?"repositorio en GitHub; ":"")+"LinkedIn y este portfolio.";var B=[["kp","8 · Socios clave",s.soc,"l"],["ka","7 · Actividades clave",a.act,"l"],["kr","6 · Recursos clave",p.t.slice(0,5).join(", ")+"; tiempo y conocimiento de la autora.","l"],["vp","2 · Propuesta de valor",p.d+" "+s.ga,"r"],["cr","4 · Relación con clientes",a.rel,"r"],["ch","3 · Canales",ch,"r"],["cs","1 · Segmentos de clientes",a.seg,"l"],["co","9 · Estructura de costes","Tiempo de desarrollo y mantenimiento; alojamiento estático.","l"],["rs","5 · Fuentes de ingresos","Sin ingresos declarados: proyecto personal y educativo.","l"]];return '<div class="bmc">'+B.map((b,i)=>'<div class="'+b[3]+' '+b[0]+'" style="grid-area:'+b[0]+';--i:'+i+'"><b>'+b[1]+'</b>'+esc(b[2])+'</div>').join("")+'</div><div class="legend"><span><i style="background:#E9A04A"></i>Hemisferio derecho: lo emocional (propuesta, relaciones, canales)</span><span><i style="background:#3978E8"></i>Hemisferio izquierdo: lógica y eficiencia</span></div><p class="note">Lienzo orientativo elaborado a partir del código y la documentación. No incluye clientes ni ingresos reales. Método: Business Model Canvas (Osterwalder y Pigneur).</p>'}
