function bkGo(i){var B=BK;i=Math.max(0,Math.min(B.sp.length-1,i));B.i=i;var x=B.sp[i],el=$("#bkv");el.className="spread"+(x.f?" full":"");el.innerHTML=x.f?'<section class="pg f">'+x.f+'<footer class="pn2">'+(2*i+1)+'</footer></section>':'<section class="pg l">'+x.l+'<footer class="pn2">'+(2*i+1)+'</footer></section><section class="pg r">'+x.r+'<footer class="pn2">'+(2*i+2)+'</footer></section>';void el.offsetWidth;el.classList.add("fl");$("#bkt").textContent=x.t+" · pág. "+(2*i+1)+(x.f?"":"–"+(2*i+2))+" de "+B.sp.length*2;$("#bkp").disabled=i<1;$("#bkn").disabled=i>=B.sp.length-1;var cur=0;BKT.forEach((t,j)=>{if(i>=t[1])cur=j});document.querySelectorAll("#bk .bkt button").forEach((b,j)=>b.toggleAttribute("aria-current",j===cur));el.querySelectorAll(".tr2 i").forEach(e=>{var v=e.style.getPropertyValue("--v");e.style.setProperty("--v","0%");setTimeout(()=>e.style.setProperty("--v",v),60)})}
function bkH(id,p,s){var sp=bkSp(id,p,s);BK={sp:sp,i:0};return '<div class="bk" id="bk" role="region" aria-label="Libro de la propuesta de valor de '+esc(p.n)+'"><div class="bkt" role="group" aria-label="Secciones del libro">'+BKT.map(t=>'<button type="button" data-go="'+t[1]+'" style="--c:'+t[2]+'">'+t[0]+'</button>').join("")+'</div><div class="bkbar"><button type="button" id="bkp">Anterior</button><span id="bkt" aria-live="polite"></span><button type="button" id="bkn" class="btn p">Siguiente</button></div><div class="spread" id="bkv"></div></div>'}
