function chl(i){var c=CH[i],b=BKO[i],col=BKB[b];return '<div class="cho" style="--c:'+col+'"><span class="chn2">'+String(i+1).padStart(2,"0")+'</span><span class="chb">Bloque '+(b+1)+'<br>'+BKN[b]+'</span></div><h4 class="cht">'+esc(c[0])+'</h4><div class="chk" style="--c:'+col+'"><div class="chd"><b>Objetivo</b>'+esc(c[1])+'</div><div class="chd tip"><b>Consejo</b>'+esc(c[2])+'</div></div>'}
function bkSum(id,p,s){var a=bkA(id,s),pos=s.pos==null?60:s.pos,zn=pos<35?"Inventa":pos<65?"Amplía":"Mejora",yes=a.q10.split(",").filter(x=>+x===2).length,avg=(a.q7.split(",").reduce((x,y)=>x+ +y,0)/7).toFixed(1),rows=a.jobs.map(j=>[j[0],j[1].split(",").reduce((x,y)=>x+ +y,0)]).sort((x,y)=>y[1]-x[1]),web=s.ar==="web",L=[web?.5:1,s.ax&&s.ax[0]===0?1:.5,1,1,1,web?.5:1,(id==="codisalud"||id==="clinexcode"||id==="blog")?.5:1],si=L.filter(v=>v===1).length;
 return ["Seis técnicas: 1 aplicada, 2 parciales y 3 pendientes de aplicar.","Posible primer evangelista: "+a.ev,"Cuatro voces simuladas: cliente, socio, dirección y comunidad.","Trabajo de mayor valor: "+rows[0][0]+" ("+rows[0][1]+" de 12 puntos).","Producto principal: "+p.f[0]+".","Frase construida con el segmento, el trabajo, la frustración y la alegría de "+p.n+".","Tres pares de encaje diseñados; producto–mercado por validar.","Factores en nivel «Sí»: "+si+" de 7.","Respuestas «Sí» en la autoevaluación: "+yes+" de 10.","Media de los siete indicadores: "+avg+" de 10 (orientativa).","Posición en el espectro: "+zn+".","Mejora prevista: "+(s.fut?s.fut[2]:"por definir")+"."]}
function bkHead(id,p,s){var a=bkA(id,s),pos=s.pos==null?60:s.pos,zn=pos<35?"Inventa":pos<65?"Amplía":"Mejora";return '<p class="bkintro">Un libro de 17 espacios que recorre el método de propuesta de valor con los datos de este proyecto: de conocer al cliente a evaluar el modelo de negocio. Lo medido o implementado está señalado; el resto son hipótesis.</p><div class="bkhead">'+[["Por qué",s.why,"Causa que mueve el proyecto","#E9A04A"],["Para quién",a.seg,"Hipótesis de cliente","#25B9A6"],["Encaje","Problema–solución diseñado","Producto–mercado: por validar","#3978E8"],["Posición",zn,"Entre inventar y mejorar","#8064DB"],["Valor",s.vals.length+" de 10 tipos",s.vals.slice(0,3).map(i=>VN[i]).join(", "),"#FF7A6B"]].map(k=>'<div class="kpi" style="--c:'+k[3]+'"><small>'+k[0]+'</small><b>'+esc(k[1])+'</b><span>'+esc(k[2])+'</span></div>').join("")+'</div>'}
function bkGo(i){var B=BK;i=Math.max(0,Math.min(B.sp.length-1,i));B.i=i;var el=$("#bkv");
 var render=function(){var x=B.sp[i];el.className="spread"+(x.f?" full":"");el.innerHTML=x.f?'<section class="pg f">'+x.f+'<footer class="pn2">'+(2*i+1)+'</footer></section>':'<section class="pg l">'+x.l+'<footer class="pn2">'+(2*i+1)+'</footer></section><section class="pg r">'+x.r+'<footer class="pn2">'+(2*i+2)+'</footer></section>';
  var sm=B.sum&&B.sum[i-3];if(i>=3&&i<=14&&sm){var t=el.querySelector(".pg.l")||el.querySelector(".pg.f");t.querySelector(".pn2").insertAdjacentHTML("beforebegin",'<div class="chsum" style="--c:'+BKB[BKO[i-3]]+'"><b>En este proyecto</b>'+esc(sm)+'</div>')}
  void el.offsetWidth;el.classList.add("fl");$("#bkt").textContent=x.t+" · pág. "+(2*i+1)+(x.f?"":"–"+(2*i+2))+" de "+B.sp.length*2;
  el.querySelectorAll(".tr2 i").forEach(e=>{var v=e.style.getPropertyValue("--v");e.style.setProperty("--v","0%");setTimeout(()=>e.style.setProperty("--v",v),60)})};
 $("#bkp").disabled=i<1;$("#bkn").disabled=i>=B.sp.length-1;$("#bk .bkprog i").style.width=((i+1)/B.sp.length*100)+"%";var cur=0;BKT.forEach((t,j)=>{if(i>=t[1])cur=j});document.querySelectorAll("#bk .bkt button,#bk .edge button").forEach((b,j)=>b.toggleAttribute("aria-current",j%BKT.length===cur));
 if(B.init&&!rm){el.classList.remove("fl");el.classList.add("out");setTimeout(function(){el.classList.remove("out");render()},140)}else{B.init=1;render()}}
